mapper.select:
SELECT COUNT(*)
  FROM ORDERS o
  JOIN ORDER_ITEMS i ON o.order_no = i.order_no
 WHERE o.order_no = #{orderNo}
   AND o.member_id = #{memberId}
   AND o.del_yn = 'N'
   AND o.order_state != 'CANCELED'
   AND i.sku = #{sku}

mapper.update:
UPDATE PRODUCT_REVIEWS
   SET del_yn = 'Y', updated_at = #{updatedAt}
 WHERE review_id = #{reviewId}
   AND sku = #{sku}
   AND member_id = #{memberId}
   AND del_yn = 'N'

mapper.select:
SELECT review_id, order_no, sku, member_id, rating, content, del_yn, created_at, updated_at
  FROM PRODUCT_REVIEWS
 WHERE review_id = #{reviewId}

SELECT r.review_id AS reviewId, r.rating, r.content, m.member_name AS memberName, r.created_at AS createdAt FROM PRODUCT_REVIEWS r JOIN MEMBERS m ON m.member_id = r.member_id WHERE r.sku = #{sku} AND r.del_yn = 'N' ORDER BY
r.rating DESC, r.created_at DESC, r.review_id DESC r.rating ASC, r.created_at DESC, r.review_id DESC r.created_at DESC, r.review_id DESC
LIMIT #{limit} OFFSET #{offset}
